class Solution:
    def houseCount(self, street: 'Street', k: int) -> int:
        for _ in range(k):
            if street.isDoorOpen():
                street.closeDoor()
            street.moveRight()
        street.openDoor()
        ans = 0
        while not street.isDoorOpen():
            street.moveRight()
            ans += 1
        return ans

c.cpp:
int houseCount(Street* street, int k) {
    for (int i = 0; i < k; i++) {
        if (street->isDoorOpen()) street->closeDoor();
        street->moveRight();
    }
    street->openDoor();
    int ans = 0;
    while (!street->isDoorOpen()) {
        street->moveRight();
        ans++;
    }
    return ans;
}

